<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Red vial — AlertaPY</title><style>:root{font-family:Inter,system-ui,sans-serif;color:#102d2a;background:#f2f6f5}body{margin:0;padding:2rem}main{max-width:1150px;margin:auto}a{color:#075eaa}section{background:#fff;border:1px solid #d9e4e1;border-radius:16px;padding:1rem;margin:1rem 0;overflow:auto}.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:.7rem}label{display:grid;gap:.25rem;font-size:.8rem;font-weight:700}input,button{min-height:40px;border:1px solid #cbd8d4;border-radius:8px;padding:0 .65rem}button{background:#0877e8;color:#fff;font-weight:800;cursor:pointer}table{width:100%;border-collapse:collapse;font-size:.82rem}th,td{text-align:left;padding:.6rem;border-bottom:1px solid #e7eeec}.notice{padding:.75rem;border-radius:10px;background:#e5f6ee}.danger{background:#b4232e}</style></head><body><main><p><a href="{{ route('admin.coverage') }}">← Estado de fuentes</a></p><h1>Cartografía · Red vial</h1><p>Importación local auditable. La validación no modifica la red activa.</p>@if(session('status'))<p class="notice">{{ session('status') }}</p>@endif @if(session('command_output'))<pre>{{ session('command_output') }}</pre>@endif<section><h2>Importar dataset</h2><form method="post" enctype="multipart/form-data">@csrf<div class="grid"><label>Archivo GeoJSON/KML/KMZ/CSV<input type="file" name="dataset" required></label><label>Nombre del dataset<input name="dataset_name" required></label><label>Fuente<input name="source_name" value="MOPC" required></label><label>URL de origen<input name="source_url" type="url"></label><label>Fecha de fuente<input name="source_date" type="date"></label><label><span>Reemplazo seguro</span><span><input name="replace" value="1" type="checkbox"> Desactivar el anterior solo después de importar</span></label></div><p><button name="mode" value="validate">Validar / Dry run</button> <button name="mode" value=